import { boot } from '@seiza/web/bootstrap';
import { createBridge } from '@seiza/duckdb/bridge';
// Generated by wasm-bindgen into web/pkg/ (gitignored); `just observatory gpui-build` builds it.
import init, { replayGeometry, replayJump, replayOpen, replayView, setTheme, start } from '../pkg/tall_table_gpui.js';
// The same asset wasm-bindgen would resolve; named here so the HTML preload and
// `init` fetch one URL (instantiateStreaming needs `application/wasm`).
import wasmUrl from '../pkg/tall_table_gpui_bg.wasm?url';
import { MARKS, followPageTheme, markAt, nextFrame, nextMark, pageTheme, publishContender } from '../../../../contract.ts';
import { DATA, ENGINE_DIR, OBSERVATORY, UI_FONT } from '../../../../paths.ts';
import { pickScenario } from '../../../../scenarios.ts';
import { FLING_FRAMES, flingStep } from '../../../../../metrics/metrics.ts';
// The level's host: the admin table's fonts toggle on the base (`base.ts`), nothing on the wide level (`market.ts` on the market's, `tail.ts` on the tail's, `wall.ts` on the wall's).
import { levelHost } from './level.ts';

/** Set by shared-web's placeholder (`PLACEHOLDER_PAINT_MARK`) and `seiza`'s
 *  bootstrap (`FIRST_FRAME_MARK`); not imported, since those modules are the
 *  build's, not the page's. */
const PLACEHOLDER_PAINTED = 'seiza:placeholder-painted';
const FIRST_FRAME = 'gpui:first-frame';

// GPUI's first pixels are the placeholder shell's, and it's usable right
// after its first frame (docs/contender-contract.md, "Marks"). Rust marks
// `open` and `filled` from the table's events.
markAt(PLACEHOLDER_PAINTED, MARKS.firstPixels);
markAt(FIRST_FRAME, MARKS.usable);

// The scenario and stop the URL asks for, on this build's level; one it
// doesn't have is a failure the window shows (`contender:failed`).
const picked = pickScenario(__LEVEL__, new URLSearchParams(location.search));
const file = picked instanceof Error ? '' : picked.scenario.data;
/** What the level sets (`crate/src/scene.rs`, `Scene::new`): on the wide
 *  sheet, the stop's lengths, the pin, the heat's first column and domain. */
const level: number[] = [];
if (!(picked instanceof Error) && picked.scenario.level === 'wide' && 'rowHeight' in picked.stop) {
  const { stop, scenario } = picked;
  const { lo, mid, hi } = scenario.heat.domain;
  level.push(stop.rowHeight, stop.textSize, stop.columnWidth, scenario.pinned, scenario.heatFrom, lo, mid, hi);
}
const host = picked instanceof Error ? undefined : levelHost(picked);
if (host) level.push(...host.numbers);
const failure = picked instanceof Error ? picked.message : (host?.failure ?? '');
/** Frames to wait for the view to change after a replay's input: GPUI
 *  handles it on its next turn and draws it in the next frame. */
const SETTLE_FRAMES = 3;

/**
 * Runs `call`, then resolves once the view it led to is filled: at the first
 * `contender:filled` after it, or at once if the view landed already filled
 * (rows in the cache) or didn't move (the same position): the table marks
 * only a change to filled, so neither sets the mark.
 */
async function untilFilled(call: () => void): Promise<void> {
  const since = performance.now();
  const [before = 0] = replayView();
  call();
  const filled = nextMark(MARKS.filled, since);
  for (let frame = 0; frame < SETTLE_FRAMES; frame++) {
    await nextFrame();
    const [frames = 0, landedFilled = 0] = replayView();
    if (frames === before) continue;
    if (landedFilled) {
      filled.catch(() => {});
      return;
    }
    await filled;
    return;
  }
  // It didn't move: done if it's filled where it is.
  if (replayView()[1]) {
    filled.catch(() => {});
    return;
  }
  await filled;
}

// GPUI replays through its own input path: script-made wheel events reach
// its listeners on the canvas.
async function fling(): Promise<void> {
  const [rows = 0, rowHeight = 0] = replayGeometry();
  const canvas = document.querySelector('canvas');
  if (!rows || !rowHeight || !canvas) throw new Error('fling: no table on screen yet');
  const { x, y, width, height } = canvas.getBoundingClientRect();
  const deltaY = flingStep(rows, rowHeight);
  const step = () => canvas.dispatchEvent(new WheelEvent('wheel', { deltaY, clientX: x + width / 2, clientY: y + height / 2, bubbles: true, cancelable: true }));
  for (let sent = 1; sent < FLING_FRAMES; sent++) {
    await nextFrame();
    step();
  }
  await nextFrame();
  // The last step, then until the view at the end is filled.
  await untilFilled(step);
}

// A frame whose scenario or stop this build lacks shows the failure and
// opens nothing: its replay fails at once rather than wait for a fill.
const unknown = (): Promise<never> => Promise.reject(picked instanceof Error ? picked : new Error('no scenario'));
/** The monitoring wall's replay is `open()` alone: a desk's 50 rows give a
 *  fling and a jump no meaning (`docs/contender-contract.md`, "Replay"). */
const noMove = (): Promise<never> => Promise.reject(new Error('the monitoring wall has no fling or jump'));
publishContender(
  'gpui',
  picked instanceof Error
    ? { open: unknown, fling: unknown, jump: unknown }
    : __LEVEL__ === 'wall'
      ? {
          // Every table refilled: the wall's filled mark, across them.
          open: () => {
            const since = performance.now();
            replayOpen();
            return nextMark(MARKS.filled, since).then(() => {});
          },
          fling: noMove,
          jump: noMove,
        }
      : {
          open: () => untilFilled(replayOpen),
          fling,
          jump: (fraction) => untilFilled(() => replayJump(fraction)),
        },
);

// The page's theme, as the window opens and live after: until the wasm has
// started, the root's `data-theme` (which `start` reads) is all there is.
let started = false;
followPageTheme((theme) => started && setTheme(theme));

// The engine's extensions are served from /observatory/duckdb/ (`contenderBuild`).
const bridge = createBridge({ extensionDir: ENGINE_DIR, extensionBase: OBSERVATORY });

void boot({
  init: () => init({ module_or_path: wasmUrl }),
  start: (font) => {
    if (!failure) host?.beforeStart();
    start(font, bridge, `${DATA}${file}`, file, Float64Array.from(level), failure, pageTheme() ?? '');
    started = true;
  },
  fontUrl: UI_FONT,
  wasmUrl,
});
